mapper.select:
select p.post_id, ifnull(t.likes, 0) as like_count,
       (own_like.id is not null) as liked, (own_favorite.id is not null) as favorited
from qt_forum_post p
left join (
    select post_id, count(*) as likes from qt_forum_post_like
    where post_id in #{id}
    group by post_id
) t on t.post_id = p.post_id
left join qt_forum_post_like own_like on own_like.post_id = p.post_id and own_like.user_id = #{userId}
left join qt_forum_post_favorite own_favorite on own_favorite.post_id = p.post_id and own_favorite.user_id = #{userId}
where p.post_id in #{id}
